schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    indirizzo TEXT
);

CREATE TABLE ordini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_ordine DATE NOT NULL,
    importo_totale NUMERIC(10,2) CHECK (importo_totale >= 0)
);

CREATE TABLE spedizioni (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini(id),
    data_spedizione DATE NOT NULL,
    destinazione TEXT NOT NULL,
    stato TEXT NOT NULL CHECK (stato IN ('in_attesa', 'in_transito', 'consegnato'))
);
